{
  "metric": "gross_margin",
  "periodA": "2026-08",
  "periodB": "2026-09",
  "answerable": true,
  "missingData": null,
  "hypotheses": [
    {
      "id": "h1",
      "driverType": "price",
      "text": "Average selling price per unit changed between August and September",
      "checks": "lightning.metastore.finmozg.finance_usl.sales_line: sum(revenue_cad)/sum(qty) grouped by period"
    },
    {
      "id": "h2",
      "driverType": "volume",
      "text": "Total units sold changed between August and September",
      "checks": "lightning.metastore.finmozg.finance_usl.sales_line: sum(qty) grouped by period"
    },
    {
      "id": "h3",
      "driverType": "mix",
      "text": "Customer or channel mix shifted between August and September",
      "checks": "lightning.metastore.finmozg.finance_usl.sales_line join lightning.metastore.finmozg.finance_usl.customer on sales_line.customer_id = customer.customer_id: sum(revenue_cad) grouped by period, channel"
    },
    {
      "id": "h4",
      "driverType": "supplier_price",
      "text": "Average purchase cost per unit changed between August and September",
      "checks": "lightning.metastore.finmozg.finance_usl.purchase_line: sum(amount_cad)/sum(qty) grouped by period"
    },
    {
      "id": "h5",
      "driverType": "fx",
      "text": "USD/CAD exchange rate movement affected cost of imported goods between August and September",
      "checks": "lightning.metastore.finmozg.finance_usl.purchase_line where currency <> 'CAD': average(fx_rate), sum(amount_cad) grouped by period"
    },
    {
      "id": "h6",
      "driverType": "packaging",
      "text": "Packaging spend changed between August and September",
      "checks": "lightning.metastore.finmozg.finance_usl.purchase_line join lightning.metastore.finmozg.finance_usl.product on purchase_line.sku = product.sku where product.category = 'Packaging': sum(amount_cad) grouped by period"
    },
    {
      "id": "h7",
      "driverType": "opex",
      "text": "Operating expense (marketing) changed between August and September",
      "checks": "lightning.metastore.finmozg.finance_usl.gl_balance where account_code = '6100': amount_cad grouped by period"
    }
  ]
}
